<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Plus,ArrowLeft,UserRound,Download} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {cardPersona,validatePersona,type Persona,type PersonaDefaults} from './persona'
import type {CharacterCard} from './card-format'
const store=useLocal(),rows=ref<Document<Persona>[]>([]),cards=ref<Document<CharacterCard>[]>([]),defaults=ref<Document<PersonaDefaults>|null>(null),editing=ref<Persona|null>(null),editingId=ref(''),revision=ref(0),search=ref(''),error=ref(''),busy=ref(false),controller=new AbortController();let disposed=false,editorEpoch=0
const visible=computed(()=>rows.value.filter(row=>(row.value.name+' '+row.value.title).toLowerCase().includes(search.value.toLowerCase())))
async function load(){const vault=store.vault;if(!vault)return;const [personas,charList,global]=await Promise.all([vault.list<Persona>('persona'),vault.list<CharacterCard>('card'),vault.read<PersonaDefaults>('settings:personas')]);if(disposed||store.vault!==vault)return;rows.value=personas;cards.value=charList;defaults.value=global}
function edit(row?:Document<Persona>){editorEpoch++;editing.value=row?JSON.parse(JSON.stringify(row.value)):{name:'新身份',description:'',title:'',enabled:true};editingId.value=row?.id||crypto.randomUUID();revision.value=row?.revision||0;error.value=''}
async function save(){const vault=store.vault;if(!vault||!editing.value||busy.value)return;busy.value=true;const epoch=editorEpoch,id=editingId.value,expected=revision.value,value=JSON.parse(JSON.stringify(editing.value)) as Persona,operation=crypto.randomUUID();try{validatePersona(value);try{await vault.commitBundle(operation,[{kind:'persona',id,expectedRevision:expected,value}],controller.signal)}catch(e){if(controller.signal.aborted||store.vault!==vault||!vault.unlocked)throw e;const receipts=await vault.receipt(operation),saved=receipts?await vault.read<Persona>(id):null;if(!saved||saved.revision!==expected+1||canonical(saved.value)!==canonical(value))throw e}if(disposed||store.vault!==vault||epoch!==editorEpoch)return;if(editing.value&&canonical(editing.value)!==canonical(value)){revision.value=expected+1;error.value='上一份修改已保存，当前内容还未保存'}else editing.value=null;await load()}catch(e){if(!disposed&&epoch===editorEpoch)error.value=(e as Error).message}finally{busy.value=false}}
async function setDefault(row:Document<Persona>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'settings:personas',expectedRevision:defaults.value?.revision||0,value:{defaultPersonaId:defaults.value?.value.defaultPersonaId===row.id?null:row.id,cardBindings:defaults.value?.value.cardBindings||{}}}],controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function bindCard(row:Document<Persona>,event:Event){const cardId=(event.target as HTMLSelectElement).value,vault=store.vault;if(!vault||!cardId||busy.value)return;busy.value=true;try{const bindings={...(defaults.value?.value.cardBindings||{})};if(bindings[cardId]===row.id)delete bindings[cardId];else bindings[cardId]=row.id;await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'settings:personas',expectedRevision:defaults.value?.revision||0,value:{defaultPersonaId:defaults.value?.value.defaultPersonaId||null,cardBindings:bindings}}],controller.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}(event.target as HTMLSelectElement).value=''}
function convert(event:Event){const row=cards.value.find(row=>row.id===(event.target as HTMLSelectElement).value);if(row){edit();editing.value=cardPersona(row)}}
function download(row:Document<Persona>){const url=URL.createObjectURL(new Blob([JSON.stringify({type:'reader-persona-v1',...row.value},null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.value.name+'.persona.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function upload(event:Event){const input=event.target as HTMLInputElement,vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const files=Array.from(input.files||[]);if(files.length>64)throw new Error('一次最多导入 64 个身份');for(const file of files){controller.signal.throwIfAborted();if(file.size>128*1024)throw new Error('身份文件超过 128 KiB');const value=JSON.parse(await file.text());if(value.type!=='reader-persona-v1')throw new Error('身份文件版本不支持');delete value.type;delete value.sourceCard;validatePersona(value);await vault.commitBundle(crypto.randomUUID(),[{kind:'persona',id:crypto.randomUUID(),expectedRevision:0,value}],controller.signal)}await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;controller.abort()})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">PERSONAS</span><h1>{{editing?editing.name:'我的身份'}}</h1></div><div class="final-page-actions"><button v-if="editing" @click="editing=null"><ArrowLeft :size="18"/>返回</button><button v-else class="final-primary" @click="edit()"><Plus :size="18"/>新建</button></div></div><p v-if="error" class="final-error" role="alert">{{error}}</p><form v-if="editing" class="final-card-form" @submit.prevent="save"><label>身份姓名<input v-model="editing.name" maxlength="200" required></label><label>身份描述<textarea v-model="editing.description" maxlength="12000" rows="8"></textarea></label><label>备注<input v-model="editing.title" maxlength="200"></label><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用</label><button class="final-primary" :disabled="busy">保存身份</button></form>
<template v-else><div class="final-page-actions"><RouterLink to="/local/characters" class="final-text-link">返回角色</RouterLink><RouterLink to="/local/lorebooks" class="final-text-link">世界书</RouterLink><RouterLink to="/local/tavern/regex" class="final-text-link">正则</RouterLink></div><label v-if="cards.length" class="final-search">从角色创建身份<select aria-label="从角色创建身份" @change="convert"><option value="">选择角色</option><option v-for="row in cards" :key="row.id" :value="row.id">{{row.value.name}}</option></select></label><label class="final-import-panel">导入身份<input type="file" accept=".json" multiple :disabled="busy" @change="upload"></label><label v-if="rows.length" class="final-search">搜索身份<input v-model="search" type="search"></label><div v-if="!rows.length" class="final-empty"><UserRound :size="40"/><h2>你想以谁的身份进入故事？</h2><button class="final-primary" @click="edit()">创建身份</button></div><div class="final-collection-grid"><article v-for="row in visible" :key="row.id" class="final-character-card"><UserRound :size="28"/><h2>{{row.value.name}}</h2><small>{{row.value.title}}</small><p>{{row.value.description.slice(0,160)}}</p><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button class="final-icon-button" :aria-label="'导出身份'+row.value.name" @click="download(row)"><Download :size="18"/></button></div><button :disabled="busy||!row.value.enabled" :aria-pressed="defaults?.value.defaultPersonaId===row.id" @click="setDefault(row)">{{defaults?.value.defaultPersonaId===row.id?'取消默认身份':'设为默认身份'}}</button><label v-if="cards.length">角色专用<select aria-label="角色专用" :disabled="busy||!row.value.enabled" @change="bindCard(row,$event)"><option value="">选择或取消绑定</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.value.name}}{{defaults?.value.cardBindings[card.id]===row.id?' · 已绑定':''}}</option></select></label></article></div></template></section></template>
